def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if history[1][1] == 'C' else 'D'
    if n == 3:
        if history[1][1] == 'D' and history[2][1] == 'D':
            return 'D'
        return 'C'

    my_ops = [h[0] for h in history]
    opp_ops = [h[1] for h in history]

    opp_c = opp_ops.count('C')
    opp_d = n - opp_c
    my_c = my_ops.count('C')
    my_d = n - my_c

    last_mine = my_ops[-1]
    last_opp = opp_ops[-1]

    # Always-defect detection
    if opp_d == n:
        return 'D'
    # Always-cooperate detection
    if opp_c == n:
        if n >= 95:
            return 'D'
        return 'C'

    # Recent window (last 12)
    start = max(0, n - 12)
    recent = history[start:]
    rec_len = len(recent)
    rec_opp_c = sum(1 for _, b in recent if b == 'C')
    rec_opp_d = rec_len - rec_opp_c
    rec_my_d = sum(1 for a, _ in recent if a == 'D')

    # Count how often opponent mirrored our previous move (TFT-like detector)
    mirror = 0
    total_pairs = n - 1
    for i in range(1, n):
        if opp_ops[i] == my_ops[i - 1]:
            mirror += 1

    opp_rate = opp_c / n

    # Endgame: last 4 rounds exploit cooperators
    remaining = 100 - n
    if remaining <= 4:
        if opp_rate >= 0.6 and rec_opp_d <= 2:
            return 'D'
        if opp_rate >= 0.85:
            return 'D'
        if opp_rate <= 0.35:
            return 'D'
        # middle: defect aggressively since endgame
        return 'D'

    # If opponent just defected
    if last_opp == 'D':
        # recent defection streak
        streak = 0
        i = n - 1
        while i >= 0 and opp_ops[i] == 'D':
            streak += 1
            i -= 1
        # Long streak -> stay defensive
        if streak >= 3:
            return 'D'
        # If opponent overall very cooperative, forgive once
        if opp_rate >= 0.75 and streak == 1:
            return 'C'
        # TFT-like opponent: retaliate but plan to forgive next
        if mirror >= total_pairs * 0.65:
            if last_mine == 'C':
                return 'D'
            return 'C'
        # If we already punished (last was D), forgive
        if last_mine == 'D':
            if opp_rate >= 0.5:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated
    # If we defected last, often return to C to fix relationship
    if last_mine == 'D':
        if opp_rate >= 0.55:
            return 'C'
        if rec_opp_d >= 4:
            return 'D'
        if rng.random() < 0.6:
            return 'C'
        return 'D'

    # Both cooperated last.
    # If opponent very cooperative: mostly cooperate but occasionally probe
    if opp_rate >= 0.8:
        # Probe rarely, spaced out
        if n >= 20 and n % 19 == 0 and rec_my_d == 0:
            return 'D'
        return 'C'

    # Moderate cooperation: TFT with occasional retaliation to avoid being exploited
    if rec_opp_d >= 5:
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    if rec_opp_d >= 1:
        # opportunistic occasional defection
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent has been perfect recently: cooperate, but rare probe
    if n >= 15 and rng.random() < 0.03:
        return 'D'
    return 'C'
